-- Tabela LOGMED: "Tabela comercial SP LOGMED 2025.26" (planilha), origem São Paulo → MS e MT.
-- Preço por grupo de cidade de destino (aba "Grupo de Cidade"): Capital I (até 50 km), Interior I (50–150 km),
-- Interior II (acima de 150 km) — cada linha vale só para as cidades da coluna destinos.
-- Frete peso por faixa (0–10 … 200–250 kg) e, acima de 250 kg, valor da faixa + excedente por kg.
-- Somados: TAS 4,80 (Centro-Oeste), taxa de entrega 14,54 até 10 kg + 0,28/kg excedente, interiorização
-- (Interior I 200,00; Interior II 300,00), ad valorem + GRIS sobre a NF, pedágio 5,70 por fração de 100 kg.
-- ICMS "conforme legislação": somado pela rota (SP → MS/MT = 7%). Cubagem 300 kg/m³.
-- Não incluídos (dependem do caso): TDE e TRT (ver lista da Logmed), agendamento, paletização, espera.
-- Rodar no SQL Editor de CADA projeto (Cuiabá e Campo Grande); pode rodar mais de uma vez.

-- 1) Coluna nova: a linha da tabela vale só para estas cidades de destino (em branco = todas)
alter table public.frete_tabelas add column if not exists destinos text;

-- 2) Linhas da Logmed (para as duas filiais)
delete from public.frete_tabelas where transportadora = 'LOGMED' and observacoes like 'Tabela comercial SP LOGMED 2025/26%';
insert into public.frete_tabelas (transportadora, rota, peso_ate, nf_ate, valor_fixo, valor_kg, pct_nf, frete_minimo, minimo_base, cubagem_kg_m3,
  pedagio_valor, pedagio_fracao_kg, gris_pct, gris_min, coleta_valor, icms_modo, vigencia_inicio, vigencia_fim, observacoes, destinos, filial)
select 'LOGMED', v.rota, v.peso_ate::numeric, null, v.fixo::numeric, v.kg::numeric, v.pct::numeric, null, 'total', 300,
       5.70, 100, null, null, null, 'somar', null, null, v.obs, v.destinos, f.filial
from (values
  ('SP - MS CAPITAL I', 10, 107.35, null, 0.45, 'Tabela comercial SP LOGMED 2025/26: MS CAPITAL I. Ad valorem 0.3% + GRIS 0.15%; TAS 4,80; taxa de entrega 14,54 ate 10 kg + 0,28/kg; pedagio 5,70/100kg; ICMS somado pela rota. Faixa ate 10 kg: 88.01.', 'CAMPO GRANDE, JARAGUARI, TERENOS'),
